package com.example.hibernatelab.g0_lifecycle;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * Khách hàng dùng {@code IDENTITY} (cột {@code generated by default as identity}) để SO SÁNH với
 * {@link Customer} (SEQUENCE) trong G0-S02.
 *
 * <p>Với IDENTITY, id chỉ có sau khi DB chạy câu INSERT. Vì vậy Hibernate buộc phải gửi INSERT NGAY
 * ở dòng {@code persist()} thay vì hoãn tới flush. Hệ quả: mất khả năng hoãn và gom SQL.
 */
@Entity(name = "G0_IdentityCustomer")
@Table(schema = "g0_lifecycle", name = "identity_customer")
public class IdentityCustomer {

	// IDENTITY: DB tự sinh id lúc INSERT, không có sequence nào được tạo cho entity này.
	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Column(name = "name", nullable = false)
	private String name;

	protected IdentityCustomer() {
		// JPA bắt buộc có constructor không tham số
	}

	public IdentityCustomer(String name) {
		this.name = name;
	}

	public Long getId() {
		return id;
	}

	public String getName() {
		return name;
	}
}
